    protected V v2;
    protected K v3;

    Triple(T v1, V v2, K v3) {
        this.v1 = v1;
        this.v2 = v2;
        this.v3 = v3;
    }

    @Override
    public String toString() {
        return v1 + " " + v2 + " " + v3;
